```python
from .parser import Select, Column, Literal, Compare, And, Or, Not, IsNull
from .tokens import SQLSyntaxError

class SQLExecutionError(Exception):
    pass

def kind_of(val) -> int:
    if val is None:
        return 0 # NULL
    if isinstance(val, bool):
        return 1 # Bool
    if isinstance(val, (int, float)):
        return 2 # Number
    if isinstance(val, str):
        return 3 # String
    return 4 # Unknown

def execute(stmt: Select, tables: dict[str, list[dict]]) -> list[dict]:
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table: {stmt.table}")

    rows = tables[stmt.table]

    # Filter
    if stmt.where:
        rows = [row for row in rows if eval_condition(stmt.where, row) is True]

    # Sort
    if stmt.order_by:
        for col_name, descending in reversed(stmt.order_by):
            try:
                # Collect non-null values to check kind consistency
                non_null_kinds = set()
                for row in rows:
                    val = row.get(col_name, None)
                    k = kind_of(val)
                    if k != 0: # Not NULL
                        non_null_kinds.add(k)
                if len(non_null_kinds) > 1:
                    raise SQLExecutionError(f"Cannot sort by column {col_name}: mixed value types")

                rows.sort(key=lambda r: r.get(col_name, None), reverse=descending)
            except TypeError:
                raise SQLExecutionError(f"Cannot sort by column {col_name}: mixed value types")

    # Limit
    if stmt.limit is not None:
        rows = rows[:stmt.limit]

    # Project
    result = []
    if stmt.columns is None: # SELECT *
        for row in rows:
            result.append(dict(row))
    else:
        for row in rows:
            result.append({name: row.get(name, None) for name in stmt.columns})

    return result

def eval_condition(cond, row: dict):
    if isinstance(cond, And):
        left = eval_condition(cond.left, row)
        if left is False: return False
        right = eval_condition(cond.right, row)
        if left is None or right is None:
            return None if (left is None or right is None) else True # Logic: if not False, and any None -> None? No.
            # AND logic:
            # True, True -> True
            # False, _ -> False
            # _, False -> False
            # None, True -> None
            # True, None -> None
            # None, None -> None

        # Re-implementing strictly per spec 5:
        # AND is false if either side is false, otherwise unknown if either side is unknown, otherwise true.

    if isinstance(cond, And):
        l = eval_condition(cond.left, row)
        r = eval_condition(cond.right, row)
        if l is False or r is False: return False
        if l is None or r is None: return None
        return True

    if isinstance(cond, Or):
        l = eval_condition(cond.left, row)
        r = eval_condition(cond.right, row)
        if l is True or r is True: return True
        if l is None or r is None: return None
        return False

    if isinstance(cond, Not):
        val = eval_condition(cond.operand, row)
        if val is None: return None
        return not val

    if isinstance(cond, Compare):
        l_val = eval_operand(cond.left, row)
        r_val = eval_operand(cond.right, row)
        return compare_op(cond.op, l_val, r_val)

    if isinstance(cond, IsNull):
        val = eval_operand(cond.operand, row)
        is_null = (val is None)
        if cond.negated:
            return not is_null
        return is_null

def eval_operand(op, row: dict):
    if isinstance(op, Column):
        return row.get(op.name, None)
    if isinstance(op, Literal):
        return op.value

def compare_op(op, left, right):
    if left is None or right is None:
        return None

    lk = kind_of(left)
    rk = kind_of(right)

    if lk != rk:
        if op == '=': return False
        if op == '!=': return True
        raise SQLExecutionError("Cannot compare different types with <, <=, >, >=")

    if op == '=': return left == right
    if op == '!=': return left != right

    try:
        if op == '<': return left < right
        if op == '>': return left > right
        if op == '<=': return left <= right
        if op == '>=': return left >= right
    except TypeError:
        raise SQLExecutionError("Cannot compare these types")

    raise SQLExecutionError(f"Unknown operator {op}")

def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from .parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)
