from dataclasses import dataclass
from typing import Any

class SQLError(Exception):
    """Base class for all SQL errors."""
    pass

class SQLSyntaxError(SQLError):
    """Raised when the SQL text is invalid."""
    def __init__(self, message: str, pos: int):
        super().__init__(message)
        self.pos = pos

@dataclass(frozen=True)
class Token:
    kind: str
    value: Any
    pos: int

def tokenize(sql: str) -> list[Token]:
    tokens = []
    i = 0
    n = len(sql)
    keywords = {
        'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'NOT', 'ORDER', 'BY', 'ASC',
        'DESC', 'LIMIT', 'IS', 'NULL', 'TRUE', 'FALSE'
    }

    while i < n:
        char = sql[i]
        # Skip whitespace
        if char.isspace():
            i += 1
            continue

        # Strings
        if char == "'":
            start = i
            i += 1
            buf = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i+1] == "'":
                        buf.append("'")
                        i += 2
                    else:
                        break
                else:
                    buf.append(sql[i])
                    i += 1
            if i >= n:
                raise SQLSyntaxError("Unterminated string literal", start)
            i += 1 # skip closing quote
            tokens.append(Token("STRING", "".join(buf), start))
            continue

        # Numbers
        # A number starts with a digit OR a minus sign followed by a digit or dot
        if char.isdigit() or (char == '-' and i + 1 < n and (sql[i+1].isdigit() or sql[i+1] == '.')):
            start = i
            if char == '-':
                i += 1

            has_digit_before_dot = False
            if i < n and sql[i].isdigit():
                while i < n and sql[i].isdigit():
                    i += 1
                has_digit_before_dot = True

            if i < n and sql[i] == '.':
                dot_pos = i
                i += 1
                has_digit_after_dot = False
                while i < n and sql[i].isdigit():
                    i += 1
                    has_digit_after_dot = True

                if not has_digit_before_dot and not has_digit_after_dot:
                    # This case shouldn't happen given entry condition, but safe guard
                    raise SQLSyntaxError("Invalid number", dot_pos)
                if not has_digit_before_dot:
                    raise SQLSyntaxError("Invalid number: missing digit before '.'", dot_pos)
                if not has_digit_after_dot:
                    raise SQLSyntaxError("Invalid number: missing digit after '.'", dot_pos)

                tokens.append(Token("NUMBER", float(sql[start:i]), start))
            else:
                tokens.append(Token("NUMBER", int(sql[start:i]), start))
            continue

        # Operators
        if char == '=':
            tokens.append(Token("OP", "=", i))
            i += 1
        elif char == '!':
            if i + 1 < n and sql[i+1] == '=':
                tokens.append(Token("OP", "!=", i))
                i += 2
            else:
                raise SQLSyntaxError(f"Unexpected character '{char}'", i)
        elif char == '<':
            if i + 1 < n and sql[i+1] == '>':
                tokens.append(Token("OP", "!=", i))
                i += 2
            elif i + 1 < n and sql[i+1] == '=':
                tokens.append(Token("OP", "<=", i))
                i += 2
            else:
                tokens.append(Token("OP", "<", i))
                i += 1
        elif char == '>':
            if i + 1 < n and sql[i+1] == '=':
                tokens.append(Token("OP", ">=", i))
                i += 2
            else:
                tokens.append(Token("OP", ">", i))
                i += 1
        elif char == '*':
            tokens.append(Token("STAR", "*", i))
            i += 1
        elif char == ',':
            tokens.append(Token("COMMA", ",", i))
            i += 1
        elif char == '(':
            tokens.append(Token("LPAREN", "(", i))
            i += 1
        elif char == ')':
            tokens.append(Token("RPAREN", ")", i))
            i += 1
        elif char.isalpha() or char == '_':
            start = i
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                i += 1
            word = sql[start:i]
            if word.upper() in keywords:
                tokens.append(Token("KEYWORD", word.upper(), start))
            else:
                tokens.append(Token("IDENT", word, start))
        else:
            raise SQLSyntaxError(f"Unexpected character '{char}'", i)

    tokens.append(Token("EOF", None, len(sql)))
    return tokens
