from .parser import Select, Column, Literal, Compare, And, Or, Not, IsNull

class SQLExecutionError(Exception):
    pass

def get_kind(val) -> int:
    """
    Returns:
    0: NULL
    1: Bool
    2: Number (int, float)
    3: String
    """
    if val is None:
        return 0
    if isinstance(val, bool):
        return 1
    if isinstance(val, (int, float)):
        return 2
    if isinstance(val, str):
        return 3
    return -1 # Should not happen in valid data

def eval_operand(op, row: dict):
    if isinstance(op, Column):
        return row.get(op.name, None)
    if isinstance(op, Literal):
        return op.value
    raise SQLExecutionError(f"Invalid operand type: {type(op)}")

def compare_values(op: str, left, right):
    lk = get_kind(left)
    rk = get_kind(right)

    # 1. NULL handling: any comparison with NULL is unknown (None)
    if lk == 0 or rk == 0:
        return None

    # 2. Different kinds
    if lk != rk:
        if op == '=':
            return False
        if op == '!=':
            return True
        # <, <=, >, >= raise error
        raise SQLExecutionError(f"Cannot compare different types with {op}")

    # 3. Same kind
    # Kinds: 1 (Bool), 2 (Number), 3 (String)
    # Python's native comparisons work correctly for these:
    # - Bools: False < True
    # - Numbers: int/float mix works naturally
    # - Strings: case-sensitive lexicographical

    if op == '=':
        return left == right
    if op == '!=':
        return left != right
    if op == '<':
        return left < right
    if op == '>':
        return left > right
    if op == '<=':
        return left <= right
    if op == '>=':
        return left >= right

    raise SQLExecutionError(f"Unknown operator: {op}")

def eval_condition(cond, row: dict):
    if isinstance(cond, And):
        l = eval_condition(cond.left, row)
        # AND is false if either side is false
        if l is False:
            return False
        r = eval_condition(cond.right, row)
        if r is False:
            return False
        # Otherwise unknown if either is unknown
        if l is None or r is None:
            return None
        # Otherwise true
        return True

    if isinstance(cond, Or):
        l = eval_condition(cond.left, row)
        # OR is true if either side is true
        if l is True:
            return True
        r = eval_condition(cond.right, row)
        if r is True:
            return True
        # Otherwise unknown if either is unknown
        if l is None or r is None:
            return None
        # Otherwise false
        return False

    if isinstance(cond, Not):
        val = eval_condition(cond.operand, row)
        if val is None:
            return None
        return not val

    if isinstance(cond, Compare):
        l_val = eval_operand(cond.left, row)
        r_val = eval_operand(cond.right, row)
