    table: str
    where: Optional[Any]
    order_by: list[tuple[str, bool]]
    limit: Optional[int]

class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def expect(self, kind: str, value: Any = None) -> Token:
        tok = self.current()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise SQLSyntaxError(f"Expected {kind} ({value if value is not None else ''}), got {tok.kind} ({tok.value})", tok.pos)
        self.pos += 1
        return tok

    def parse(self) -> Select:
        stmt = self.parse_select()
        self.expect("EOF")
        return stmt

    def parse_select(self) -> Select:
        self.expect("KEYWORD", "SELECT")
        columns = self.parse_select_list()
        self.expect("KEYWORD", "FROM")
        table_tok = self.expect("IDENT")
        table_name = table_tok.value

        where = None
        if self.current().kind == "KEYWORD" and self.current().value == "WHERE":
            self.pos += 1
            where = self.parse_condition()

        order_by = []
        if self.current().kind == "KEYWORD" and self.current().value == "ORDER":
            self.pos += 1
            self.expect("KEYWORD", "BY")
            order_by = self.parse_order_by()

        limit = None
        if self.current().kind == "KEYWORD" and self.current().value == "LIMIT":
            self.pos += 1
            limit_tok = self.expect("NUMBER")
            if not isinstance(limit_tok.value, int) or limit_tok.value < 0:
                raise SQLSyntaxError("LIMIT must be a non-negative integer", limit_tok.pos)
            limit = limit_tok.value

        return Select(columns, table_name, where, order_by, limit)

    def parse_select_list(self) -> Optional[list[str]]:
        if self.current().kind == "STAR":
            self.pos += 1
            return None

        columns = []
        seen = set()
        while True:
            tok = self.expect("IDENT")
            name = tok.value
            if name in seen:
                raise SQLSyntaxError(f"Duplicate column name {name}", tok.pos)
            seen.add(name)
            columns.append(name)
            if self.current().kind == "COMMA":
                self.pos += 1
            else:
                break
        return columns

    def parse_condition(self) -> Any:
        return self.parse_or()

    def parse_or(self) -> Any:
        node = self.parse_and()
        while self.current().kind == "KEYWORD" and self.current().value == "OR":
            self.pos += 1
            right = self.parse_and()
            node = Or(node, right)
        return node

    def parse_and(self) -> Any:
        node = self.parse_not()
        while self.current().kind == "KEYWORD" and self.current().value == "AND":
            self.pos += 1
            right = self.parse_not()
            node = And(node, right)
        return node

    def parse_not(self) -> Any:
        if self.current().kind == "KEYWORD" and self.current().value == "NOT":
            self.pos += 1
            operand = self.parse_not()
            return Not(operand)
        return self.parse_comparison()

    def parse_comparison(self) -> Any:
        if self.current().kind == "LPAREN":
            self.pos += 1
            node = self.parse_condition()
            self.expect("RPAREN")
            return node

        operand = self.parse_operand()

        if self.current().kind == "KEYWORD" and self.current().value == "IS":
            self.pos += 1
            negated = False
            if self.current().kind == "KEYWORD" and self.current().value == "NOT":
                negated = True
                self.pos += 1
            self.expect("KEYWORD", "NULL")
            return IsNull(operand, negated)

        if self.current().kind == "OP":
            op = self.current().value
            self.pos += 1
            right = self.parse_operand()
            return Compare(op, operand, right)

        tok = self.current()
        raise SQLSyntaxError(f"Expected operator or IS NULL, got {tok.kind} ({tok.value})", tok.pos)

    def parse_operand(self) -> Any:
        tok = self.current()
        if tok.kind == "IDENT":
            self.pos += 1
            return Column(tok.value)
        elif tok.kind == "NUMBER":
            self.pos += 1
            return Literal(tok.value)
        elif tok.kind == "STRING":
            self.pos += 1
            return Literal(tok.value)
        elif tok.kind == "KEYWORD":
            if tok.value == "NULL":
                self.pos += 1
                return Literal(None)
            elif tok.value == "TRUE":
                self.pos += 1
                return Literal(True)
            elif tok.value == "FALSE":
                self.pos += 1
                return Literal(False)

        raise SQLSyntaxError(f"Unexpected token in operand: {tok.kind} ({tok.value})", tok.pos)

    def parse_order_by(self) -> list[tuple[str, bool]]:
        items = []
        while True:
            tok = self.expect("IDENT")
            name = tok.value
            descending = False
            if self.current().kind == "KEYWORD" and self.current().value == "DESC":
                descending = True
                self.pos += 1
            elif self.current().kind == "KEYWORD" and self.current().value == "ASC":
                self.pos += 1

            items.append((name, descending))

            if self.current().kind == "COMMA":
                self.pos += 1
            else:
                break
        return items

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()
