import math


def _escape_string(s: str, ensure_ascii: bool) -> str:
    result = ['"']
    for char in s:
        if char == '"':
            result.append('\\"')
        elif char == '\\':
            result.append('\\\\')
        elif char == '\b':
            result.append('\\b')
        elif char == '\f':
            result.append('\\f')
        elif char == '\n':
            result.append('\\n')
        elif char == '\r':
            result.append('\\r')
        elif char == '\t':
            result.append('\\t')
        elif ord(char) < 0x20:
            result.append('\\u{:04x}'.format(ord(char)))
        elif ensure_ascii and ord(char) > 0x7F:
            if ord(char) > 0xFFFF:
                # Surrogate pair
                cp = ord(char)
                # Python 3.12 handles surrogatepass? No, we need manual encoding.
                # Codepoint > 0xFFFF
                # High surrogate = 0xD800 + ((cp - 0x10000) >> 10)
                # Low surrogate = 0xDC00 + ((cp - 0x10000) & 0x3FF)
                hi = 0xD800 + ((cp - 0x10000) >> 10)
                lo = 0xDC00 + ((cp - 0x10000) & 0x3FF)
                result.append('\\u{:04x}\\u{:04x}'.format(hi, lo))
            else:
                result.append('\\u{:04x}'.format(ord(char)))
        else:
            result.append(char)
    result.append('"')
    return ''.join(result)


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False) -> str:
    if indent is not None:
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non-negative integer")

    def _dump(val, level: int, seen: set):
        # Cycle detection
        # Containers are dict, list, tuple
        if isinstance(val, (dict, list, tuple)):
            obj_id = id(val)
            if obj_id in seen:
                raise ValueError("circular reference detected")
            seen.add(obj_id)

        if val is None:
            return "null"
        if val is True:
            return "true"
        if val is False:
            return "false"

        if isinstance(val, float):
            if math.isnan(val) or math.isinf(val):
                raise ValueError("NaN or Infinity is not JSON-serializable")
            return repr(val)

        if isinstance(val, int):
            return str(val)

        if isinstance(val, str):
            return _escape_string(val, ensure_ascii)

        if isinstance(val, (list, tuple)):
            if not val:
                return "[]"

            items = []
            for item in val:
                items.append(_dump(item, level + 1, seen))

            if indent is not None:
                pad = ' ' * (indent * level)
                inner_pad = ' ' * (indent * (level + 1))
                body = ',\n'.join(inner_pad + item for item in items)
                return '[\n' + body + '\n' + pad + ']'
            else:
                return '[' + ','.join(items) + ']'

        if isinstance(val, dict):
            if not val:
                return "{}"

            # Check keys are strings
            for k in val:
                if not isinstance(k, str):
                    raise TypeError(f"dict keys must be strings, got {type(k).__name__}")

            items = []

            if sort_keys:
                keys = sorted(val.keys())
            else:
                keys = val.keys()

            for k in keys:
                k_str = _escape_string(k, ensure_ascii)
                v_str = _dump(val[k], level + 1, seen)
                items.append((k_str, v_str))

            if indent is not None:
                pad = ' ' * (indent * level)
                inner_pad = ' ' * (indent * (level + 1))
                body_lines = []
                for k_str, v_str in items:
                    # Format: "key": value
                    body_lines.append(f'{inner_pad}{k_str}: {v_str}')
                body = ',\n'.join(body_lines)
                return '{\n' + body + '\n' + pad + '}'
            else:
                body_parts = []
                for k_str, v_str in items:
                    body_parts.append(f'{k_str}:{v_str}')
                return '{' + ','.join(body_parts) + '}'

        # Unsupported type
        raise TypeError(f"Object of type {type(val).__name__} is not JSON serializable")

    # Start dump with level 0
    # We need a way to pass initial seen set. 
    # The _dump function handles adding to seen.
    return _dump(obj, 0, set())
