from typing import NamedTuple, List


class JSONError(ValueError):
    def __init__(self, msg: str, line: int, column: int):
        super().__init__(f"{msg} at line {line} column {column}")
        self.msg = msg
        self.line = line
        self.column = column


class Token(NamedTuple):
    kind: str
    value: object
    line: int
    column: int


def _is_ascii_letter(c: str) -> bool:
    return c in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'


def _is_digit(c: str) -> bool:
    return c in '0123456789'


def _is_hex_digit(c: str) -> bool:
    return c in '0123456789abcdefABCDEF'


def tokenize(text: str) -> List[Token]:
    tokens: List[Token] = []
    n = len(text)
    i = 0

    # Position tracking
    line = 1
    column = 1

    def advance(count: int):
        nonlocal i, line, column
        for k in range(count):
            if text[i] == '\n':
                line += 1
                column = 1
            else:
                column += 1
            i += 1

    while i < n:
        c = text[i]

        # Whitespace
        if c in ' \t\n\r':
            advance(1)
            continue

        start_line = line
        start_col = column

        # Punctuation
        if c in '{}[]:,':
            tokens.append(Token(kind=c, value=None, line=start_line, column=start_col))
            advance(1)
            continue

        # Literals and Unknown Letters
        if _is_ascii_letter(c):
            j = i
            while j < n and _is_ascii_letter(text[j]):
                j += 1
            word = text[i:j]
            if word == 'true':
                tokens.append(Token(kind='TRUE', value=True, line=start_line, column=start_col))
                advance(j - i)
                continue
            elif word == 'false':
                tokens.append(Token(kind='FALSE', value=False, line=start_line, column=start_col))
                advance(j - i)
                continue
            elif word == 'null':
                tokens.append(Token(kind='NULL', value=None, line=start_line, column=start_col))
                advance(j - i)
                continue
            else:
                raise JSONError("invalid literal", start_line, start_col)

        # Numbers
        if c == '-' or _is_digit(c):
            j = i
            while j < n and text[j] in '0123456789+-.eE':
                j += 1
            num_str = text[i:j]

            # Validate JSON number grammar
            # optional '-'
            # then '0' or [1-9][0-9]*
            # optionally '.' [0-9]+
            # optionally [eE] [+-]? [0-9]+

            valid = True
            pos = 0
            length = len(num_str)

            # Optional minus
            if pos < length and num_str[pos] == '-':
                pos += 1

            # Integer part
            if pos >= length:
                valid = False
            elif num_str[pos] == '0':
                pos += 1
                if pos < length and _is_digit(num_str[pos]):
                    valid = False # Leading zero not allowed unless it's just 0
            elif _is_digit(num_str[pos]):
                pos += 1
                while pos < length and _is_digit(num_str[pos]):
                    pos += 1
            else:
                valid = False

            # Fraction
            if valid and pos < length and num_str[pos] == '.':
                pos += 1
                if pos >= length or not _is_digit(num_str[pos]):
                    valid = False
                else:
                    while pos < length and _is_digit(num_str[pos]):
                        pos += 1

            # Exponent
            if valid and pos < length and num_str[pos] in 'eE':
                pos += 1
                if pos < length and num_str[pos] in '+-':
                    pos += 1
                if pos >= length or not _is_digit(num_str[pos]):
                    valid = False
                else:
                    while pos < length and _is_digit(num_str[pos]):
                        pos += 1

            if not valid or pos != length:
                raise JSONError("invalid number", start_line, start_col)

            # Determine type and value
            # If it contains '.' or 'e'/'E' it's float, else int.
            # -0 is int 0.

            has_frac_exp = False
            for ch in num_str:
                if ch in '.eE':
                    has_frac_exp = True
                    break

            if has_frac_exp:
                val = float(num_str)
                tokens.append(Token(kind='NUMBER', value=val, line=start_line, column=start_col))
            else:
                val = int(num_str)
                # int handles -0 correctly as 0 in Python? int("-0") is 0.
                tokens.append(Token(kind='NUMBER', value=val, line=start_line, column=start_col))

            advance(j - i)
            continue

        # Strings
        if c == '"':
            # Start string scanning
            advance(1) # consume opening quote
            sb = []
            terminated = False

            while i < n:
                ch = text[i]
                if ch == '"':
                    terminated = True
                    advance(1)
                    break

                # Control character check (must happen before handling anything else inside string)
                # Spec: "a raw control character (U+0000–U+001F) inside a string: at that character."
                if ord(ch) < 0x20:
                    # Error at this character
                    raise JSONError("invalid character in string", line, column)

                if ch == '\\':
                    backslash_line, backslash_col = line, column
                    advance(1)
                    if i >= n:
                        raise JSONError("invalid escape sequence", backslash_line, backslash_col)

                    esc = text[i]

                    if esc == '"' or esc == '\\' or esc == '/':
                        sb.append(esc)
                        advance(1)
                    elif esc == 'b':
                        sb.append('\b')
                        advance(1)
                    elif esc == 'f':
                        sb.append('\f')
                        advance(1)
                    elif esc == 'n':
                        sb.append('\n')
                        advance(1)
                    elif esc == 'r':
                        sb.append('\r')
                        advance(1)
                    elif esc == 't':
                        sb.append('\t')
                        advance(1)
                    elif esc == 'u':
                        advance(1)
                        if i + 4 > n:
                            raise JSONError("invalid unicode escape", backslash_line, backslash_col)
                        hex_str = text[i:i+4]
                        if not all(_is_hex_digit(h) for h in hex_str):
                            raise JSONError("invalid unicode escape", backslash_line, backslash_col)

                        code_point = int(hex_str, 16)
                        advance(4)

                        # Handle surrogates
                        if 0xD800 <= code_point <= 0xDBFF:
                            # High surrogate, must be followed by \u low surrogate
                            if i >= n or text[i] != '\\' or i + 6 > n or text[i+1] != 'u':
                                raise JSONError("invalid unicode escape", backslash_line, backslash_col)

                            next_hex_str = text[i+2:i+6]
                            if not all(_is_hex_digit(h) for h in next_hex_str):
                                raise JSONError("invalid unicode escape", backslash_line, backslash_col)

                            low_code = int(next_hex_str, 16)
                            if not (0xDC00 <= low_code <= 0xDFFF):
                                raise JSONError("invalid unicode escape", backslash_line, backslash_col)

                            # Calculate surrogate pair
                            combined = 0x10000 + ((code_point - 0xD800) << 10) + (low_code - 0xDC00)
                            sb.append(chr(combined))
                            advance(6) # \, u, and 4 hex digits
                        elif 0xDC00 <= code_point <= 0xDFFF:
                            # Low surrogate on its own
                            raise JSONError("invalid unicode escape", backslash_line, backslash_col)
                        else:
                            sb.append(chr(code_point))
                    else:
                        raise JSONError("invalid escape sequence", backslash_line, backslash_col)
                else:
                    sb.append(ch)
                    advance(1)

            if not terminated:
                # Error at opening quote
                # start_line, start_col were saved before advancing
                raise JSONError("unterminated string", start_line, start_col)

            tokens.append(Token(kind='STRING', value=''.join(sb), line=start_line, column=start_col))
            continue

        # Unexpected character
        raise JSONError("unexpected character", start_line, start_col)

    # EOF token
    tokens.append(Token(kind='EOF', value=None, line=line, column=column))
    return tokens
