from .scanner import tokenize, Token, JSONError


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_kind: str = None) -> Token:
        token = self.tokens[self.pos]
        if expected_kind is not None and token.kind != expected_kind:
            raise JSONError(f"expected {expected_kind}, got {token.kind}", token.line, token.column)
        self.pos += 1
        return token

    def parse_value(self):
        token = self.peek()
        if token.kind == 'STRING':
            return self.consume().value
        if token.kind == 'NUMBER':
            return self.consume().value
        if token.kind == 'TRUE':
            return self.consume().value
        if token.kind == 'FALSE':
            return self.consume().value
        if token.kind == 'NULL':
            return self.consume().value
        if token.kind == '{':
            return self.parse_object()
        if token.kind == '[':
            return self.parse_array()
        if token.kind == 'EOF':
            raise JSONError("unexpected end of input", token.line, token.column)

        # Any other token (like a lone punctuation or error)
        # If it's punctuation that isn't { or [, it's unexpected here.
        raise JSONError(f"unexpected token {token.kind}", token.line, token.column)

    def parse_object(self):
        obj = {}
        # Consume '{'
        self.consume('{')

        if self.peek().kind == '}':
            self.consume('}')
            return obj

        while True:
            # Expect string key
            token = self.peek()
            if token.kind != 'STRING':
                raise JSONError(f"expected string key, got {token.kind}", token.line, token.column)
            key = self.consume().value

            # Expect ':'
            token = self.peek()
            if token.kind != ':':
                raise JSONError(f"expected ':', got {token.kind}", token.line, token.column)
            self.consume(':')

            # Expect value
            value = self.parse_value()

            # Assign key. If key exists, overwrite value but keep position.
            # Python dict preserves insertion order. If we assign to existing key, 
            # the position remains where it first appeared.
            obj[key] = value

            # Expect ',' or '}'
            token = self.peek()
            if token.kind == '}':
                self.consume('}')
                break
            elif token.kind == ',':
                self.consume(',')
                # After comma, next must be a key, unless trailing comma error?
                # Spec says "a trailing comma as in ... {"a":1,}" is error.
                # So if next is '}', it's an error at that token.
                # If next is EOF, it's an error at EOF.
                # We loop back to top, where "Expect string key" will fail.
                continue
            else:
                raise JSONError(f"expected ',' or '}}', got {token.kind}", token.line, token.column)

        return obj

    def parse_array(self):
        arr = []
        # Consume '['
        self.consume('[')

        if self.peek().kind == ']':
            self.consume(']')
            return arr

        while True:
            # Expect value
            value = self.parse_value()
            arr.append(value)

            # Expect ',' or ']'
            token = self.peek()
            if token.kind == ']':
                self.consume(']')
                break
            elif token.kind == ',':
                self.consume(',')
                # Trailing comma check: if next is ']', error at ']'
                # The loop continues, parse_value will be called.
                # If next is ']', parse_value fails with "unexpected token ]" at that position.
                # Spec says "a trailing comma as in [1,] ... is an error at that token".
                # That token is ']'.
                continue
            else:
                raise JSONError(f"expected ',' or ']', got {token.kind}", token.line, token.column)

        return arr


def loads(text: str):
    tokens = tokenize(text)
    parser = Parser(tokens)

    if tokens[0].kind == 'EOF':
        raise JSONError("empty input", tokens[0].line, tokens[0].column)

    value = parser.parse_value()

    # Check for trailing content
    token = parser.peek()
    if token.kind != 'EOF':
        raise JSONError("unexpected content after top-level value", token.line, token.column)

    return value
